383	    private void notifyUsersAndUpdateSaleStatus(Xdg64 order, Xbf54 payment) {
384	        try {
385	            log.info("결제 관련 알림 및 판매 상태 업데이트 시작: 주문ID={}", order.getId());
388	            Xzj27 orderBid = order.getOrderBid();
389	            if (orderBid == null) {
391	                Xzz58 saleBid = saleBidQueryService.findByOrderId(order.getId());
392	                if (saleBid == null) {
393	                    log.warn("주문에 연결된 판매 입찰 정보가 없습니다: 주문ID={}", order.getId());
394	                    return;
395	                }
397	                Xgg74 sale = saleBid.getSale();
398	                if (sale == null) {
399	                    log.warn("판매 입찰에 연결된 판매 정보가 없습니다: 판매입찰ID={}", saleBid.getId());
400	                    return;
401	                }
403	                sendNotifications(order, sale);
404	                sale.updateStatus(Xgg74Status.SOLD);
405	                log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
406	                return;
407	            }
410	            Xgg74 sale = orderBid.getSale();
411	            if (sale == null) {
412	                log.warn("주문 입찰에 연결된 판매 정보가 없습니다: 주문입찰ID={}", orderBid.getId());
413	                return;
414	            }
416	            sendNotifications(order, sale);
419	            sale.updateStatus(Xgg74Status.SOLD);
420	            log.info("판매 상태 업데이트 완료: 판매ID={}, 상태=SOLD", sale.getId());
421	        } catch (Exception e) {
423	            log.error("결제 관련 알림 및 판매 상태 업데이트 중 오류 발생: 주문ID={}, 오류={}",
424	                    order.getId(), e.getMessage(), e);
425	        }
426	    }
