532	        }
533	    }
542	    @Transactional
543	    public String refundPayment(Long paymentId) {
544	        Instant start = Instant.now();
545	        try {
546	            log.info("결제 환불 요청 시작: 결제ID={}", paymentId);
549	            Xbf54 payment = paymentRepository.findById(paymentId)
550	                    .orElseThrow(() -> new Xvt76Exception("결제 ID: " + paymentId + "를 찾을 수 없습니다."));
553	            if (!payment.getStatus().canTransitionTo(Xbf54Status.REFUND_REQUESTED)) {
554	                throw new Xbf54Exception(Xbf54ErrorCode.INVALID_PAYMENT_STATUS,
555	                        "현재 상태에서 환불 요청을 진행할 수 없습니다. 현재 상태: " + payment.getStatus());
556	            }
559	            if (payment.getImpUid() == null || payment.getImpUid().isBlank()) {
560	                throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_CANCELLATION_FAILED,
561	                        "환불 가능한 결제 ID가 없습니다.");
562	            }
564	            boolean refundSuccess = portOneApiClient.cancelPayment(payment.getImpUid());
566	            if (refundSuccess) {
567	                payment.updateStatus(Xbf54Status.REFUNDED);
568	                paymentRepository.save(payment);
569	                log.info("결제 환불 요청 성공: 결제ID={}, 상태=REFUNDED", paymentId);
572	                sendRefundNotification(payment);
575	                Instant end = Instant.now();
576	                Duration duration = Duration.between(start, end);
577	                log.debug("결제 환불 처리 시간: {}ms", duration.toMillis());
579	                return "환불이 성공적으로 완료되었습니다.";
580	            } else {
581	                payment.updateStatus(Xbf54Status.REFUND_REQUESTED);
